    other_count = 26 - len(distinct)

    def trans(f, c):
        g = [0] * (N + 1)
        for j in range(1, N + 1):
            v = f[j]
            if g[j - 1] > v:
                v = g[j - 1]
            if c is not None and S[j - 1] == c:
                t = f[j - 1] + 1
                if t > v:
                    v = t
            g[j] = v
        return tuple(g)

    dp = {tuple([0] * (N + 1)): 1}
    for _ in range(M):
        ndp = defaultdict(int)
        for st, cnt in dp.items():
            for c in distinct:
                ns = trans(st, c)
                ndp[ns] = (ndp[ns] + cnt) % MOD
            if other_count > 0:
                ns = trans(st, None)
                ndp[ns] = (ndp[ns] + cnt * other_count) % MOD
        dp = ndp

    ans = [0] * (N + 1)
    for st, cnt in dp.items():
        ans[st[N]] = (ans[st[N]] + cnt) % MOD
    print(" ".join(map(str, ans)))

