    if not all('a' <= ch <= 'z' for ch in s):
        return False
    return True


def _lcs(a, b):
    la, lb = len(a), len(b)
    dp = [[0] * (lb + 1) for _ in range(la + 1)]
    for i in range(1, la + 1):
        for j in range(1, lb + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[la][lb]


def ref(inp):
    toks = inp.split()
    n = int(toks[0])
    m = int(toks[1])
    s = toks[2]
    alphabet = "abcdefghijklmnopqrstuvwxyz"
    counts = [0] * (n + 1)
    for t in product(alphabet, repeat=m):
        w = "".join(t)
        counts[_lcs(w, s)] += 1
    return " ".join(str(c % MOD) for c in counts)
